   * @param humidityAssessment payload for data port humidityAssessment
   */
  def put_concrete_inputs(airAssessment : Cabin_Air_Care_Supervisor.AirAssessment.Type,
                          humidityAssessment : Cabin_Air_Care_Supervisor.HumidityAssessment.Type): Unit = {
    put_airAssessment(airAssessment)
    put_humidityAssessment(humidityAssessment)
  }


  /** helper function to check ObservationConfidenceGuardian_airCareSupervisionProcess_observationConfidenceGuardian's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param measurementConfidence method that will be called with the value of the outgoing data
   *        port 'measurementConfidence'.
   */
  def check_concrete_output(measurementConfidence: Cabin_Air_Care_Supervisor.MeasurementConfidence.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val measurementConfidenceValue: Cabin_Air_Care_Supervisor.MeasurementConfidence.Type = get_measurementConfidence().get
    if(!measurementConfidence(measurementConfidenceValue)) {
      testFailures = testFailures :+ st"'measurementConfidence' did not match expected: value of the outgoing data port is ${measurementConfidenceValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_airAssessment(value : Cabin_Air_Care_Supervisor.AirAssessment.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_observationConfidenceGuardian.operational_api.airAssessment_Id, Cabin_Air_Care_Supervisor.AirAssessment_Payload(value))
  }

  // setter for in DataPort
  def put_humidityAssessment(value : Cabin_Air_Care_Supervisor.HumidityAssessment.Type): Unit = {
