  }

  // getter for out DataPort
  def get_measurementConfidence(): Option[Cabin_Air_Care_Supervisor.MeasurementConfidence.Type] = {
    val value: Option[Cabin_Air_Care_Supervisor.MeasurementConfidence.Type] = get_measurementConfidence_payload() match {
      case Some(Cabin_Air_Care_Supervisor.MeasurementConfidence_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port measurementConfidence.  Expecting 'Cabin_Air_Care_Supervisor.MeasurementConfidence_Payload' but received ${v}")
      case _ => None[Cabin_Air_Care_Supervisor.MeasurementConfidence.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_measurementConfidence_payload(): Option[Cabin_Air_Care_Supervisor.MeasurementConfidence_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_observationConfidenceGuardian.initialization_api.measurementConfidence_Id).asInstanceOf[Option[Cabin_Air_Care_Supervisor.MeasurementConfidence_Payload]]
